SELECT log_id, username, operation, table_name, record_id, old_value, new_value, CONVERT(VARCHAR(19), op_time, 120) AS op_time FROM OperationLog
AND table_name = #{tableName}
AND operation = #{operation}
AND (record_id LIKE #{keyword} OR old_value LIKE #{keyword} OR new_value LIKE #{keyword})
ORDER BY op_time DESC
